function useData(collectionName, defaults, cloud, user) {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  useEffect(() => {
    setError('')
    if (cloud && user) {
      const unsub = onSnapshot(collection(db, collectionName), snap => {
        setItems(snap.docs.map(d => ({ id: d.id, ...d.data() })))
        setLoading(false)
      }, err => { console.error(err); setError(`No se pudo cargar ${collectionName}. Revisa las reglas de Firestore.`); setLoading(false) })
      return () => unsub()
    }
    if (!cloud) {
      try {
        const raw = localStorage.getItem(`alabanza:${collectionName}`)
        const data = raw ? JSON.parse(raw) : (defaults || [])
        setItems(data)
        if (!raw) localStorage.setItem(`alabanza:${collectionName}`, JSON.stringify(data))
      } catch { setItems(defaults || []) }
      setLoading(false)
    }
  }, [collectionName, cloud, user?.uid])
  const upsert = async (item) => {
    const record = { ...item, id: item.id || uid(), updatedAt: new Date().toISOString() }
    if (cloud && user) {
      const { id, ...data } = record
      await setDoc(doc(db, collectionName, id), data, { merge: true })
    } else {
      setItems(prev => {
        const next = prev.some(x => x.id === record.id) ? prev.map(x => x.id === record.id ? record : x) : [record, ...prev]
        localStorage.setItem(`alabanza:${collectionName}`, JSON.stringify(next))
        return next
      })
    }
    return record
  }
  const remove = async (id) => {
    if (cloud && user) await deleteDoc(doc(db, collectionName, id))
    else setItems(prev => { const next = prev.filter(x => x.id !== id); localStorage.setItem(`alabanza:${collectionName}`, JSON.stringify(next)); return next })
  }
  const replaceAll = async (records) => {
    for (const record of records) await upsert(record)
  }
  return { items, setItems, loading, error, upsert, remove, replaceAll }
}

function LoginScreen() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (e) => {
    e.preventDefault(); setBusy(true); setMessage('')
    try { await signInWithEmailAndPassword(auth, email.trim(), password) }
    catch (err) { setMessage(err.code === 'auth/invalid-credential' ? 'Correo o contraseña incorrectos.' : 'No se pudo iniciar sesión. Revisa los datos y la configuración de Firebase.') }
    finally { setBusy(false) }
  }
  const reset = async () => {
    if (!email.trim()) { setMessage('Escribe tu correo para recibir el enlace de recuperación.'); return }
    try { await sendPasswordResetEmail(auth, email.trim()); setMessage('Te enviamos un enlace para restablecer tu contraseña.') }
    catch { setMessage('No se pudo enviar el correo. Verifica la dirección ingresada.') }
  }
  return <div className="login-shell"><div className="login-left"><div className="brand login-brand"><span className="brand-mark"><Music2 size={20}/></span><span>alabanza</span></div><div className="login-form-wrap"><div className="eyebrow">GESTIÓN DE EQUIPO</div><h1>Bienvenido de vuelta</h1><p className="muted">Inicia sesión para organizar los servicios de tu iglesia.</p><form onSubmit={submit} className="login-form"><label>Correo electrónico</label><div className="input-icon"><Mail size={17}/><input type="email" placeholder="nombre@iglesia.cl" value={email} onChange={e => setEmail(e.target.value)} required/></div><label>Contraseña</label><div className="input-icon"><LockKeyhole size={17}/><input type={showPassword ? 'text' : 'password'} placeholder="Tu contraseña" value={password} onChange={e => setPassword(e.target.value)} required/><button type="button" className="icon-btn subtle" onClick={() => setShowPassword(!showPassword)} aria-label="Mostrar contraseña">{showPassword ? <EyeOff size={17}/> : <Eye size={17}/>}</button></div>{message && <div className="inline-alert">{message}</div>}<button className="btn primary full" disabled={busy}>{busy ? 'Ingresando…' : 'Iniciar sesión'} <ArrowRight size={17}/></button><button type="button" className="link-btn" onClick={reset}>¿Olvidaste tu contraseña?</button></form><div className="login-footnote"><ShieldCheck size={15}/> Acceso protegido mediante Firebase Authentication.</div></div><div className="login-footer">Una sola plataforma para servir mejor.</div></div><div className="login-art"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="art-orbit orbit-three"/><div className="art-note"><div className="art-note-icon"><CalendarDays size={19}/></div><span>Todo listo para el domingo</span><CheckCircle2 size={18}/></div><div className="art-main"><span className="art-kicker">ORDEN · EQUIPO · REPERTORIO</span><h2>Un equipo.<br/><em>Un mismo propósito.</em></h2><p>Planifica cada servicio con claridad y prepara a tu equipo para lo que importa.</p><div className="art-dots"><i/><i/><i/><i/></div></div><div className="art-quote">“Cantad a Jehová cántico nuevo.” <span>— Salmos 96:1</span></div></div></div>
}

function AppRoot() {
  const [user, setUser] = useState(null)
  const [authReady, setAuthReady] = useState(!firebaseConfigured)
  useEffect(() => {
    if (!firebaseConfigured) return
    return onAuthStateChanged(auth, u => { setUser(u); setAuthReady(true) })
  }, [])
  if (!authReady) return <div className="loading-screen"><div className="loader"/><span>Preparando tu espacio…</span></div>
  if (firebaseConfigured && !user) return <LoginScreen/>
  return <AppShell user={user} cloud={firebaseConfigured}/>
}

function AppShell({ user, cloud }) {
  const servicesStore = useData('services', demoDefaults.services, cloud, user)
  const songsStore = useData('songs', demoDefaults.songs, cloud, user)
  const peopleStore = useData('people', demoDefaults.people, cloud, user)
  const teamsStore = useData('teams', demoDefaults.teams, cloud, user)
  const typesStore = useData('serviceTypes', demoDefaults.serviceTypes, cloud, user)
  const notesStore = useData('notes', demoDefaults.notes, cloud, user)
  const services = servicesStore.items, songs = songsStore.items, people = peopleStore.items, teams = teamsStore.items, serviceTypes = typesStore.items
  const [page, setPage] = useState('services')
  const [selectedServiceId, setSelectedServiceId] = useState('v1')
  const [serviceTab, setServiceTab] = useState('order')
  const [query, setQuery] = useState('')
  const [notice, setNotice] = useState('')
  const [modal, setModal] = useState(null)
  const [monthCursor, setMonthCursor] = useState(new Date(today.getFullYear(), today.getMonth(), 1))
  const [selectedDay, setSelectedDay] = useState(seedServices[0]?.date || today.toISOString().slice(0, 10))
  const [peopleSubtab, setPeopleSubtab] = useState('people')
  const [expandedTypes, setExpandedTypes] = useState(['t2', 't3'])
  const [accountMenu, setAccountMenu] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [busy, setBusy] = useState(false)

  useEffect(() => { if (services.length && !services.some(s => s.id === selectedServiceId)) setSelectedServiceId(services[0].id) }, [services, selectedServiceId])
  const selectedService = services.find(s => s.id === selectedServiceId) || null
  const allLoading = [servicesStore, songsStore, peopleStore, teamsStore, typesStore, notesStore].some(s => s.loading)
  const storeError = [servicesStore, songsStore, peopleStore, teamsStore, typesStore, notesStore].find(s => s.error)?.error
  const flash = (msg) => { setNotice(msg); window.clearTimeout(flash._timer); flash._timer = window.setTimeout(() => setNotice(''), 3200) }
  const navigate = (next) => { setPage(next); setQuery(''); setMobileNav(false) }

  const createService = async (data) => {
    const record = { id: uid(), title: data.title, date: data.date, typeId: data.typeId || '', startTime: data.startTime || '11:00', order: [{ id: uid(), name: 'ALABANZA', items: [] }, { id: uid(), name: 'ADORACIÓN', items: [] }], teamAssignments: {}, notes: '', rehearsalNotes: '', files: [] }
    await servicesStore.upsert(record); setSelectedServiceId(record.id); setServiceTab('order'); navigate('service-detail'); setModal(null); flash('Servicio creado correctamente.')
  }
  const updateService = async (record) => { await servicesStore.upsert(record); setModal(null); flash('Cambios guardados.') }
  const deleteService = async (id) => { if (!window.confirm('¿Eliminar este servicio? Esta acción no se puede deshacer.')) return; await servicesStore.remove(id); if (selectedServiceId === id) navigate('services'); flash('Servicio eliminado.') }
  const seedCloud = async () => {
    if (!window.confirm('Se agregarán datos de ejemplo a las colecciones vacías. ¿Continuar?')) return
    setBusy(true)
    try { await Promise.all([[servicesStore, demoDefaults.services], [songsStore, demoDefaults.songs], [peopleStore, demoDefaults.people], [teamsStore, demoDefaults.teams], [typesStore, demoDefaults.serviceTypes]].map(async ([store, records]) => { if (!store.items.length) await store.replaceAll(records) })); flash('Datos de ejemplo agregados a Firebase.') }
    catch (e) { console.error(e); flash('No se pudieron cargar los datos. Revisa las reglas de Firestore.') }
    finally { setBusy(false) }
  }
  const shellNav = [
    { id: 'services', label: 'Servicios', icon: CalendarDays },
    { id: 'songs', label: 'Canciones', icon: ListMusic },
    { id: 'media', label: 'Archivos', icon: Folder },
    { id: 'people', label: 'Personas', icon: Users },
  ]

  if (allLoading) return <div className="loading-screen"><div className="loader"/><span>Cargando tus servicios…</span></div>
  return <div className="app-frame">
    <header className="topbar"><button className="mobile-menu icon-btn" onClick={() => setMobileNav(!mobileNav)}><Menu size={20}/></button><button className="brand top-brand" onClick={() => navigate('services')}><span className="brand-mark"><Music2 size={19}/></span><span>alabanza</span><ChevronDown size={14} className="brand-chevron"/></button><nav className="top-nav">{shellNav.map(n => <button key={n.id} className={`top-nav-item ${page === n.id || (n.id === 'services' && page === 'service-detail') ? 'active' : ''}`} onClick={() => navigate(n.id)}>{n.label}</button>)}</nav><div className="top-spacer"/><button className="search-shortcut" onClick={() => document.querySelector('.global-search')?.focus()}><Search size={17}/><span>Buscar</span><kbd>⌘ K</kbd></button><button className="icon-btn notification-btn" onClick={() => flash('No tienes notificaciones nuevas.')} aria-label="Notificaciones"><Bell size={19}/><i/></button><div className="account-wrap"><button className="account-btn" onClick={() => setAccountMenu(!accountMenu)}><span className="avatar avatar-main">{initials(user?.email?.split('@')[0] || 'IR')}</span><span className="account-name">{user?.email?.split('@')[0] || 'Modo demo'}</span><ChevronDown size={14}/></button>{accountMenu && <div className="account-popover"><div className="account-popover-head"><strong>{user?.email || 'Modo demostración'}</strong><span>{cloud ? 'Conectado a Firebase' : 'Guardado en este navegador'}</span></div>{cloud ? <button onClick={() => signOut(auth)}><LogOut size={15}/> Cerrar sesión</button> : <button onClick={() => flash('Configura Firebase para habilitar cuentas y sincronización en la nube.')}><Settings size={15}/> Configurar sincronización</button>}</div>}</div></header>
    <div className="notice-bar"><span className="notice-dot"><Activity size={14}/></span><span>{cloud ? 'Espacio conectado a Firebase. Los cambios se sincronizan en la nube.' : 'Estás en modo demostración. Los cambios se guardan en este navegador.'}</span><button onClick={() => setAccountMenu(false)} aria-label="Cerrar aviso"><X size={15}/></button></div>
    <div className="app-body">
      <aside className={`sidebar ${mobileNav ? 'open' : ''}`}><div className="workspace-switch"><span className="workspace-icon"><Music size={18}/></span><span><strong>Casa de Alabanza</strong><small>Equipo de alabanza</small></span><ChevronDown size={15}/></div><div className="sidebar-label">ESPACIO DE TRABAJO</div>{shellNav.map(n => { const Icon = n.icon; return <button key={n.id} className={`side-link ${page === n.id || (n.id === 'services' && page === 'service-detail') ? 'selected' : ''}`} onClick={() => navigate(n.id)}><Icon size={18}/><span>{n.label}</span>{n.id === 'services' && <span className="side-count">{services.length}</span>}</button> })}<div className="sidebar-divider"/><div className="sidebar-label">HERRAMIENTAS</div><button className={`side-link ${page === 'schedule' ? 'selected' : ''}`} onClick={() => navigate('schedule')}><CalendarDays size={18}/><span>Mi agenda</span></button><button className={`side-link ${page === 'teams' ? 'selected' : ''}`} onClick={() => navigate('teams')}><Guitar size={18}/><span>Equipos</span></button><button className={`side-link ${page === 'settings' ? 'selected' : ''}`} onClick={() => navigate('settings')}><Settings size={18}/><span>Configuración</span></button><div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><CircleHelp size={17}/></div><strong>¿Necesitas ayuda?</strong><p>Organiza a tu equipo con todo en un solo lugar.</p><button onClick={() => setModal({ kind: 'help' })}>Ver guía rápida <ArrowRight size={14}/></button></div><div className="sidebar-user"><span className="avatar avatar-small">{initials(user?.email?.split('@')[0] || 'IR')}</span><div><strong>{user?.email?.split('@')[0] || 'Usuario demo'}</strong><small>{user ? user.email : 'Administrador'}</small></div><button className="icon-btn subtle" onClick={() => setAccountMenu(!accountMenu)}><MoreHorizontal size={18}/></button></div></div></aside>
      <main className="main-content">
        {storeError && <div className="error-banner"><ShieldCheck size={16}/>{storeError}</div>}
        {page === 'services' && <ServicesPage services={services} serviceTypes={serviceTypes} songs={songs} people={people} monthCursor={monthCursor} setMonthCursor={setMonthCursor} selectedDay={selectedDay} setSelectedDay={setSelectedDay} expandedTypes={expandedTypes} setExpandedTypes={setExpandedTypes} setModal={setModal} createService={createService} openService={s => { setSelectedServiceId(s.id); setServiceTab('order'); navigate('service-detail') }} cloud={cloud} seedCloud={seedCloud} busy={busy} />}
        {page === 'service-detail' && selectedService && <ServiceDetail service={selectedService} servicesStore={servicesStore} cloud={cloud} songs={songs} people={people} teams={teams} serviceTypes={serviceTypes} tab={serviceTab} setTab={setServiceTab} setModal={setModal} updateService={updateService} deleteService={deleteService} flash={flash} />}
        {page === 'service-detail' && !selectedService && <EmptyState icon={CalendarDays} title="Todavía no hay servicios" body="Crea el primer servicio de tu iglesia para comenzar a planificar." action="Crear servicio" onAction={() => setModal({ kind: 'service', value: null })}/>}
        {page === 'songs' && <SongsPage songs={songs} songsStore={songsStore} query={query} setQuery={setQuery} setModal={setModal} flash={flash}/>}
        {page === 'people' && <PeoplePage people={people} peopleStore={peopleStore} teams={teams} teamsStore={teamsStore} query={query} setQuery={setQuery} subtab={peopleSubtab} setSubtab={setPeopleSubtab} setModal={setModal} flash={flash}/>}
        {page === 'teams' && <TeamsPage teams={teams} people={people} teamsStore={teamsStore} setModal={setModal} flash={flash}/>}
        {page === 'media' && <MediaPage services={services} songs={songs} setModal={setModal}/>}
        {page === 'schedule' && <MySchedule services={services} people={people} openService={s => {setSelectedServiceId(s.id);setServiceTab('order');navigate('service-detail')}} />}
        {page === 'settings' && <SettingsPage cloud={cloud} user={user} services={services} onSeed={seedCloud} busy={busy} flash={flash} />}
      </main>
    </div>
    <div className="utility-rail"><button onClick={() => setModal({ kind: 'help' })} aria-label="Ayuda"><CircleHelp size={19}/></button><button onClick={() => flash('No tienes notificaciones nuevas.')} aria-label="Notificaciones"><Bell size={19}/></button><button onClick={() => navigate('schedule')} aria-label="Agenda"><CalendarDays size={19}/></button><button onClick={() => navigate('songs')} aria-label="Canciones"><Music2 size={19}/></button><button onClick={() => setModal({ kind: 'help' })} aria-label="Ideas"><Sparkles size={19}/></button></div>
    <AppEventsBridge onNavigate={navigate} onDuplicate={async record => { await servicesStore.upsert(record); setSelectedServiceId(record.id); navigate('service-detail'); flash('Servicio duplicado.') }} onDeleteService={deleteService} onSectionUpdate={async data => { await servicesStore.upsert(data.service); flash('Sección actualizada.') }} />
    {modal && <ModalHost modal={modal} setModal={setModal} onCreateService={createService} onUpdateService={updateService} onDeleteService={deleteService} onSaveSong={async d => { const rec = await songsStore.upsert(d); setModal(null); flash('Canción guardada.'); return rec }} onDeleteSong={id => songsStore.remove(id)} onSavePerson={async d => { await peopleStore.upsert(d); setModal(null); flash('Integrante guardado.') }} onSaveType={async d => { await typesStore.upsert(d); setModal(null); flash('Tipo de servicio guardado.') }} onSaveTeam={async d => { await teamsStore.upsert(d); setModal(null); flash('Equipo guardado.') }} songs={songs} people={people} teams={teams} serviceTypes={serviceTypes} services={services} />}
    {notice && <div className="toast"><CheckCircle2 size={17}/>{notice}<button onClick={() => setNotice('')}><X size={14}/></button></div>}
  </div>
}

function PageHeading({ eyebrow, title, description, actions }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="heading-actions">{actions}</div>}</div> }
function SectionTitle({ title, meta, actions }) { return <div className="section-title"><div><h2>{title}</h2>{meta && <span>{meta}</span>}</div>{actions}</div> }
function Btn({ children, variant = 'default', size = '', ...props }) { return <button className={`btn ${variant} ${size}`} {...props}>{children}</button> }
function EmptyState({ icon: Icon = Folder, title, body, action, onAction }) { return <div className="empty-state"><div className="empty-icon"><Icon size={24}/></div><h2>{title}</h2><p>{body}</p>{action && <Btn variant="primary" onClick={onAction}><Plus size={16}/>{action}</Btn>}</div> }

function MiniCalendar({ services, monthCursor, setMonthCursor, selectedDay, setSelectedDay }) {
  const year = monthCursor.getFullYear(), month = monthCursor.getMonth()
  const firstDay = (new Date(year, month, 1).getDay() + 6) % 7
  const daysInMonth = new Date(year, month + 1, 0).getDate()
  const prevDays = new Date(year, month, 0).getDate()
  const cells = Array.from({ length: 42 }, (_, i) => {
    const dayNum = i - firstDay + 1
    const date = dayNum < 1 ? new Date(year, month - 1, prevDays + dayNum) : dayNum > daysInMonth ? new Date(year, month + 1, dayNum - daysInMonth) : new Date(year, month, dayNum)
    return { date, day: date.getDate(), inMonth: date.getMonth() === month, iso: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
  })
  const scheduled = new Set(services.map(s => s.date))
  return <div className="calendar-widget"><div className="calendar-head"><strong>{monthName(monthCursor)}</strong><div className="calendar-arrows"><button onClick={() => setMonthCursor(new Date(year, month - 1, 1))}><ChevronLeft size={15}/></button><button onClick={() => setMonthCursor(new Date())} title="Ir al mes actual"><span>•</span></button><button onClick={() => setMonthCursor(new Date(year, month + 1, 1))}><ChevronRight size={15}/></button></div></div><div className="calendar-grid calendar-weekdays">{['LU','MA','MI','JU','VI','SÁ','DO'].map(d => <span key={d}>{d}</span>)}</div><div className="calendar-grid">{cells.slice(0, 35).map((c, i) => <button key={i} className={`calendar-day ${!c.inMonth ? 'outside' : ''} ${selectedDay === c.iso ? 'current' : ''} ${c.iso === today.toISOString().slice(0,10) ? 'today' : ''}`} onClick={() => {setSelectedDay(c.iso); if (!c.inMonth) setMonthCursor(new Date(c.date.getFullYear(), c.date.getMonth(), 1))}}>{c.day}{scheduled.has(c.iso) && <i/>}</button>)}</div><button className="calendar-link" onClick={() => { setSelectedDay(''); setMonthCursor(new Date(today.getFullYear(), today.getMonth(), 1)) }}>Ver calendario completo <ArrowRight size={13}/></button></div>
}

function ServicesPage({ services, serviceTypes, songs, people, monthCursor, setMonthCursor, selectedDay, setSelectedDay, expandedTypes, setExpandedTypes, setModal, createService, openService, cloud, seedCloud, busy }) {
  const [view, setView] = useState('list')
  const selectedServices = services.filter(s => !selectedDay || s.date === selectedDay).sort((a,b) => (a.date || '').localeCompare(b.date || ''))
  const upcoming = [...services].sort((a,b) => (a.date || '').localeCompare(b.date || '')).filter(s => s.date >= today.toISOString().slice(0,10))
  const fmtTime = d => { const [h,m] = (d.startTime || '11:00').split(':').map(Number); const hh = h % 12 || 12; return `${hh}:${String(m).padStart(2,'0')} ${h >= 12 ? 'pm' : 'am'}` }
  const dateOverview = selectedDay ? fmtDate(selectedDay, { weekday: 'long', day: 'numeric', month: 'long' }) : 'Próximos servicios'
  const toggleType = id => setExpandedTypes(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id])
  return <>
    <div className="context-strip"><span className="context-dot"/> CASA DE ALABANZA <span className="context-sep">/</span> PLANIFICACIÓN</div>
    <PageHeading eyebrow="PLANIFICACIÓN" title="Servicios" description="Organiza cada reunión, prepara el repertorio y coordina a tu equipo." actions={<><Btn onClick={() => setView(view === 'list' ? 'calendar' : 'list')}><CalendarDays size={16}/>{view === 'list' ? 'Vista calendario' : 'Vista lista'}</Btn><Btn variant="primary" onClick={() => setModal({ kind: 'service', value: null })}><Plus size={17}/>Nuevo servicio</Btn></>}/>
    <div className="service-overview-grid"><div className="calendar-column"><MiniCalendar services={services} monthCursor={monthCursor} setMonthCursor={setMonthCursor} selectedDay={selectedDay} setSelectedDay={setSelectedDay}/><div className="day-agenda"><div className="mini-section-head"><span>{selectedDay ? dateOverview : 'ESTA SEMANA'}</span><span className="count-pill">{selectedServices.length}</span></div>{selectedServices.length ? selectedServices.slice(0, 3).map(s => <button className="agenda-item" key={s.id} onClick={() => openService(s)}><span className="agenda-line"/><span className="agenda-copy"><strong>{s.title}</strong><small>{s.startTime || 'Hora por definir'} · {serviceTypes.find(t => t.id === s.typeId)?.category || 'Servicio'}</small></span></button>) : <div className="agenda-empty">No hay servicios para esta fecha.</div>}{selectedDay && <button className="text-link" onClick={() => setModal({ kind: 'service', value: { date: selectedDay } })}><Plus size={13}/> Agregar a este día</button>}</div></div>
      <div className="service-types-column"><div className="service-types-head"><div><SectionTitle title="Tipos de servicio" meta={`${serviceTypes.length} plantillas`}/></div><button className="btn small" onClick={() => setModal({ kind: 'type', value: null })}><Plus size={15}/> Añadir tipo</button></div>
        {view === 'calendar' ? <div className="calendar-list-large"><div className="calendar-list-top"><button onClick={() => setMonthCursor(new Date(monthCursor.getFullYear(), monthCursor.getMonth()-1, 1))}><ChevronLeft size={18}/></button><h3>{monthName(monthCursor)}</h3><button onClick={() => setMonthCursor(new Date(monthCursor.getFullYear(), monthCursor.getMonth()+1, 1))}><ChevronRight size={18}/></button></div>{Array.from({length:new Date(monthCursor.getFullYear(),monthCursor.getMonth()+1,0).getDate()},(_,i)=>i+1).map(day=>{const date=`${monthCursor.getFullYear()}-${String(monthCursor.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const matches=services.filter(s=>s.date===date);return <button key={date} className={`calendar-event-row ${selectedDay===date?'chosen':''}`} onClick={()=>setSelectedDay(date)}><span className="calendar-event-date"><b>{day}</b><small>{new Intl.DateTimeFormat('es-CL',{weekday:'short'}).format(new Date(`${date}T12:00:00`))}</small></span><span className="calendar-event-content">{matches.length ? matches.map(s=><span key={s.id} onClick={e=>{e.stopPropagation();openService(s)}} className="calendar-event-pill">{s.title}</span>) : <span className="no-event">Sin servicios programados</span>}</span></button>})}</div> : <div className="service-type-list">{serviceTypes.map((type, idx) => {const matches = services.filter(s => s.typeId === type.id);const expanded = expandedTypes.includes(type.id);return <div className="service-type-group" key={type.id}><div className="service-type-row"><button className="type-expand" onClick={() => toggleType(type.id)}>{expanded ? <ChevronDown size={16}/> : <ChevronRight size={16}/>}</button><button className="type-main" onClick={() => matches[0] ? openService(matches[0]) : setModal({ kind: 'service', value: { typeId: type.id, title: type.name } })}><span className={`type-color ${type.color || 'green'}`}/><span>{type.name}</span><small>{matches.length} {matches.length === 1 ? 'servicio' : 'servicios'}</small></button><div className="type-actions"><button className="type-view-btn" onClick={() => matches[0] ? openService(matches[0]) : setModal({ kind: 'service', value: { typeId: type.id, title: type.name } })}>Ver plan <ChevronDown size={13}/></button><button className="icon-btn subtle" onClick={() => setModal({ kind: 'type', value: type })} title="Editar tipo"><Settings size={16}/></button><button className="icon-btn subtle" onClick={() => setModal({ kind: 'service', value: { typeId: type.id, title: type.name } })} title="Crear servicio"><Plus size={17}/></button></div></div>{expanded && <div className="type-expanded">{matches.length ? matches.map(s => <button key={s.id} className="type-service-row" onClick={() => openService(s)}><span className="type-service-date"><CalendarDays size={14}/>{fmtDate(s.date,{day:'numeric',month:'short'})}</span><span>{s.title}</span><span className="type-service-time"><Clock3 size={13}/>{fmtTime(s)}</span><ChevronRight size={15}/></button>) : <div className="type-no-services">No hay servicios programados en esta plantilla. <button onClick={() => setModal({ kind: 'service', value: { typeId: type.id, title: type.name } })}>Crear el primero <ArrowRight size={13}/></button></div>}</div>}</div>})}</div>}
        <div className="schedule-summary"><div className="summary-icon"><CalendarPlus size={18}/></div><div><strong>{upcoming.length} próximos servicios</strong><p>{songs.length} canciones en repertorio · {people.length} integrantes registrados</p></div><button className="icon-btn" onClick={() => setModal({ kind: 'service', value: null })}><Plus size={17}/></button></div>
        {cloud && services.length === 0 && <div className="seed-callout"><div><strong>¿Primera vez aquí?</strong><p>Carga registros de ejemplo para explorar todas las funciones.</p></div><Btn variant="primary" size="small" onClick={seedCloud} disabled={busy}>{busy ? 'Cargando…' : 'Cargar ejemplos'}</Btn></div>}
      </div></div>
    <div className="below-fold-grid"><div className="panel"><SectionTitle title="Próximos servicios" meta="Ordenados por fecha" actions={<button className="text-link" onClick={() => setView('calendar')}>Ver calendario <ArrowRight size={14}/></button>}/>{upcoming.length ? <div className="upcoming-list">{upcoming.slice(0,4).map((s,i)=><button key={s.id} className="upcoming-row" onClick={() => openService(s)}><div className="date-tile"><small>{new Intl.DateTimeFormat('es-CL',{month:'short'}).format(new Date(`${s.date}T12:00:00`)).toUpperCase()}</small><strong>{new Date(`${s.date}T12:00:00`).getDate()}</strong></div><div className="upcoming-info"><strong>{s.title}</strong><span>{serviceTypes.find(t=>t.id===s.typeId)?.category || 'Servicio'} · {s.startTime || 'Hora por definir'}</span></div><span className="upcoming-status"><i/> Planificable</span><ChevronRight size={17}/></button>)}</div>:<p className="muted pad">No hay servicios próximos. Crea uno para empezar.</p>}</div><div className="panel quick-panel"><SectionTitle title="Accesos rápidos"/><button onClick={() => setModal({kind:'song',value:null})}><span className="quick-icon lavender"><Music2 size={17}/></span><span><strong>Agregar canción</strong><small>Ampliar el repertorio</small></span><Plus size={16}/></button><button onClick={() => setModal({kind:'person',value:null})}><span className="quick-icon mint"><UserRound size={17}/></span><span><strong>Invitar integrante</strong><small>Completar el equipo</small></span><Plus size={16}/></button><button onClick={() => setModal({kind:'type',value:null})}><span className="quick-icon peach"><CalendarDays size={17}/></span><span><strong>Crear plantilla</strong><small>Reutilizar un servicio</small></span><Plus size={16}/></button></div></div>
  </>
}

function ServiceDetail({ service, servicesStore, cloud, songs, people, teams, serviceTypes, tab, setTab, setModal, updateService, deleteService, flash }) {
  const type = serviceTypes.find(t => t.id === service.typeId)
  const [newSection, setNewSection] = useState(false)
  const [sectionName, setSectionName] = useState('')
  const [songSearch, setSongSearch] = useState('')
  const [uploadingFiles, setUploadingFiles] = useState(false)
  const uploadFiles = async (fileList) => {
    if (!fileList.length) return
    if (!cloud || !storage) { flash('Para subir archivos necesitas conectar Firebase Storage y configurar VITE_FIREBASE_STORAGE_BUCKET.'); return }
    const tooLarge = fileList.find(file => file.size > 30 * 1024 * 1024)
    if (tooLarge) { flash(`“${tooLarge.name}” supera el límite de 30 MB.`); return }
    setUploadingFiles(true)
    try {
      const uploaded = []
      for (const file of fileList) {
        const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_')
        const path = `service-files/${service.id}/${Date.now()}-${safeName}`
        const objectRef = storageRef(storage, path)
        await uploadBytes(objectRef, file, { contentType: file.type || 'application/octet-stream' })
        const url = await getDownloadURL(objectRef)
        uploaded.push({ id: uid(), name: file.name, size: file.size, type: file.type || 'Archivo', url, storagePath: path, uploadedAt: new Date().toISOString() })
      }
      await servicesStore.upsert({ ...service, files: [...(service.files || []), ...uploaded] })
      flash(uploaded.length === 1 ? 'Archivo adjuntado al servicio.' : `${uploaded.length} archivos adjuntados al servicio.`)
    } catch (err) { console.error(err); flash('No se pudieron subir los archivos. Revisa las reglas de Firebase Storage.') }
    finally { setUploadingFiles(false) }
  }
  const removeFile = async (file) => {
    if (!window.confirm(`¿Quitar “${file.name}” de este servicio?`)) return
    try { if (storage && file.storagePath) await deleteObject(storageRef(storage, file.storagePath)); await servicesStore.upsert({ ...service, files: (service.files || []).filter(f => f.id !== file.id) }); flash('Adjunto eliminado.') } catch (err) { console.error(err); flash('No se pudo eliminar el archivo. Revisa las reglas de Storage.') }
  }
  const durationSeconds = (service.order || []).flatMap(s => s.items || []).reduce((sum, item) => { const p = (item.duration || '0:00').split(':').map(Number); return sum + (p[0] || 0)*60 + (p[1] || 0) }, 0)
  const durationText = `${Math.floor(durationSeconds/60)}:${String(durationSeconds%60).padStart(2,'0')}`
  const patch = (changes) => servicesStore.upsert({ ...service, ...changes })
  const patchOrder = order => patch({ order })
  const addSong = (sectionId, song) => { const order = (service.order||[]).map(section => section.id === sectionId ? { ...section, items: [...(section.items||[]), { id: uid(), songId: song.id, title: song.title, key: song.key || 'C', duration: song.duration || '0:00' }] } : section); patchOrder(order); setSongSearch(''); flash(`“${song.title}” agregado al servicio.`) }
  const removeSong = (sectionId, itemId) => patchOrder((service.order||[]).map(section => section.id === sectionId ? { ...section, items: section.items.filter(x => x.id !== itemId) } : section))
  const moveSong = (sectionId, idx, delta) => { const order=(service.order||[]).map(section=>{if(section.id!==sectionId)return section;const items=[...section.items];const dest=idx+delta;if(dest<0||dest>=items.length)return section;[items[idx],items[dest]]=[items[dest],items[idx]];return {...section,items}});patchOrder(order) }
  const updateSongItem = (sectionId,itemId,changes) => patchOrder((service.order||[]).map(section=>section.id===sectionId?{...section,items:section.items.map(item=>item.id===itemId?{...item,...changes}:item)}:section))
  const addSection = () => { if(!sectionName.trim())return; patchOrder([...(service.order||[]),{id:uid(),name:sectionName.trim().toUpperCase(),items:[]}]);setSectionName('');setNewSection(false) }
  const toggleMember = (instrument, memberId) => { const current = service.teamAssignments || {}; const list = current[instrument] || []; const next = list.includes(memberId) ? list.filter(id => id !== memberId) : [...list, memberId]; patch({ teamAssignments: { ...current, [instrument]: next } }) }
  const roleBuckets = teams.flatMap(team => (team.groups || []).map(group => ({ ...group, teamName: team.name })))
  const groups = roleBuckets.length ? roleBuckets : [{name:'Bajo',instruments:['Bajo'],memberIds:[]},{name:'Batería',instruments:['Batería'],memberIds:[]},{name:'Guitarra acústica',instruments:['Guitarra acústica'],memberIds:[]},{name:'Guitarra eléctrica',instruments:['Guitarra eléctrica'],memberIds:[]},{name:'Keys',instruments:['Teclado'],memberIds:[]},{name:'Ministro',instruments:['Voz'],memberIds:[]},{name:'Coros',instruments:['Voz'],memberIds:[]},{name:'FOH',instruments:['Audio'],memberIds:[]}]
  return <>
    <div className="detail-breadcrumb"><button onClick={() => window.dispatchEvent(new CustomEvent('alabanza:navigate',{detail:'services'}))}><ArrowLeft size={15}/> Servicios</button><span>/</span><span>{type?.category || 'Servicio'}</span></div>
    <div className="detail-header"><div><div className="eyebrow">CASA DE ALABANZA · {type?.category?.toUpperCase() || 'PLAN DE SERVICIO'}</div><h1>{service.title}</h1><div className="detail-meta"><span><CalendarDays size={15}/>{fmtDate(service.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span><span><Clock3 size={15}/>{service.startTime || 'Hora por definir'}</span><span className="meta-dot"/><span>{(service.order||[]).flatMap(s=>s.items||[]).length} canciones</span><span>Duración estimada {durationText}</span></div></div><div className="heading-actions"><Btn onClick={() => setModal({kind:'service',value:service})}><Edit3 size={15}/>Editar</Btn><button className="icon-btn bordered" onClick={() => window.print()} title="Imprimir plan"><Printer size={17}/></button><button className="icon-btn bordered" onClick={() => setModal({kind:'service-actions',value:service})}><MoreHorizontal size={18}/></button></div></div>
    <div className="service-tabs"><button className={tab==='order'?'active':''} onClick={()=>setTab('order')}><ListMusic size={17}/>Orden <span>{(service.order||[]).flatMap(s=>s.items||[]).length}</span></button><button className={tab==='teams'?'active':''} onClick={()=>setTab('teams')}><Users size={17}/>Equipos <span>{Object.values(service.teamAssignments||{}).flat().length}</span></button><button className={tab==='rehearse'?'active':''} onClick={()=>setTab('rehearse')}><Headphones size={17}/>Ensayo</button></div>
    {tab==='order' && <div className="detail-content order-layout"><div className="order-main"><div className="order-toolbar"><div><h2>Orden del servicio</h2><p>Organiza la música y los momentos de la reunión.</p></div><div className="order-actions"><Btn onClick={() => setNewSection(!newSection)}><Plus size={15}/>Agregar sección</Btn><button className="icon-btn bordered" onClick={() => window.print()}><Printer size={16}/></button></div></div>{newSection && <form className="add-section-form" onSubmit={e=>{e.preventDefault();addSection()}}><input autoFocus value={sectionName} onChange={e=>setSectionName(e.target.value)} placeholder="Nombre de la sección, por ej. ORACIÓN"/><Btn variant="primary" type="submit">Agregar</Btn><Btn onClick={()=>setNewSection(false)}>Cancelar</Btn></form>}
      <div className="order-table"><div className="order-table-head"><span>ORDEN</span><span>TÍTULO</span><span>TONO</span><span>DURACIÓN</span><span/></div>{(service.order||[]).map(section=><div className="order-section" key={section.id}><div className="order-section-head"><span className="section-grip"><GripVertical size={14}/></span><strong>{section.name}</strong><span className="section-count">{section.items?.length || 0} canciones</span><div className="section-controls"><button onClick={()=>setModal({kind:'section-edit',value:{service,section}})} title="Editar sección"><Settings size={14}/></button><button onClick={()=>patchOrder((service.order||[]).filter(s=>s.id!==section.id))} title="Eliminar sección"><Trash2 size={14}/></button></div></div>{(section.items||[]).map((item,i)=><div className="order-item" key={item.id}><div className="order-item-grip"><button onClick={()=>moveSong(section.id,i,-1)} disabled={i===0} title="Subir"><ArrowDown className="move-up" size={13}/></button><button onClick={()=>moveSong(section.id,i,1)} disabled={i===section.items.length-1} title="Bajar"><ArrowDown size={13}/></button></div><div className="order-item-title"><span className="song-mini-icon"><Music2 size={15}/></span><button onClick={()=>setModal({kind:'song',value:songs.find(s=>s.id===item.songId)||item})}><strong>{item.title}</strong><small>{songs.find(s=>s.id===item.songId)?.artist || 'Canción del repertorio'}</small></button></div><select value={item.key||'C'} aria-label="Tonalidad" onChange={e=>updateSongItem(section.id,item.id,{key:e.target.value})}>{['C','C#','Db','D','Eb','E','F','F#','Gb','G','Ab','A','Bb','B','Cm','C#m','Dm','Ebm','Em','Fm','F#m','Gm','G#m','Am','Bbm','Bm'].map(k=><option key={k}>{k}</option>)}</select><input className="duration-input" value={item.duration||'0:00'} onChange={e=>updateSongItem(section.id,item.id,{duration:e.target.value})} aria-label="Duración"/><div className="order-item-actions"><button onClick={()=>moveSong(section.id,i,-1)} title="Mover arriba"><ChevronLeft size={15}/></button><button onClick={()=>removeSong(section.id,item.id)} title="Quitar canción"><X size={15}/></button></div></div>)}<div className="add-song-row"><Search size={15}/><input value={songSearch} onChange={e=>setSongSearch(e.target.value)} placeholder="Buscar o agregar canción al bloque…"/><button onClick={()=>setModal({kind:'song',value:null,returnTo:'service'})}><Plus size={14}/> Nueva canción</button>{songSearch && <div className="song-search-results">{songs.filter(s=>s.title.toLowerCase().includes(songSearch.toLowerCase())).slice(0,5).map(song=><button key={song.id} onClick={()=>addSong(section.id,song)}><span><strong>{song.title}</strong><small>{song.key} · {song.bpm ? `${song.bpm} BPM` : 'Sin BPM'}</small></span><Plus size={15}/></button>)}{!songs.some(s=>s.title.toLowerCase().includes(songSearch.toLowerCase()))&&<span className="no-search-results">No hay coincidencias.</span>}</div>}</div></div>)}</div>
      <div className="order-footer"><span><Clock3 size={15}/> Duración total estimada</span><strong>{durationText}</strong><span className="footer-sep"/><span>{(service.order||[]).flatMap(s=>s.items||[]).length} canciones</span><button className="text-link" onClick={()=>patch({order:[...(service.order||[]),{id:uid(),name:'NUEVA SECCIÓN',items:[]}]})}><Plus size={14}/>Sección vacía</button></div></div>
      <aside className="order-aside"><div className="panel info-panel"><div className="aside-title"><h3>Resumen del servicio</h3><button className="icon-btn subtle" onClick={()=>setModal({kind:'service',value:service})}><Edit3 size={14}/></button></div><div className="summary-line"><span>Fecha</span><strong>{fmtDate(service.date,{day:'numeric',month:'short',year:'numeric'})}</strong></div><div className="summary-line"><span>Hora de inicio</span><strong>{service.startTime || 'Por definir'}</strong></div><div className="summary-line"><span>Tipo</span><strong>{type?.category || 'Servicio'}</strong></div><div className="summary-line"><span>Canciones</span><strong>{(service.order||[]).flatMap(s=>s.items||[]).length}</strong></div><div className="summary-line"><span>Duración</span><strong>{durationText}</strong></div><div className="aside-progress"><div><span>Planificación</span><strong>{(service.order||[]).flatMap(s=>s.items||[]).length ? 'En progreso' : 'Por comenzar'}</strong></div><div className="progress-track"><i style={{width:(service.order||[]).flatMap(s=>s.items||[]).length?'68%':'12%'}}/></div></div></div><div className="panel note-panel"><div className="aside-title"><h3>Notas del servicio</h3><FileText size={16}/></div><textarea value={service.notes||''} onChange={e=>servicesStore.upsert({...service,notes:e.target.value})} placeholder="Indicaciones para el equipo, anuncios o detalles importantes…"/><span className="autosave"><Check size={12}/> Se guarda al escribir</span></div><div className="panel files-panel"><div className="aside-title"><h3>Archivos</h3><label className={`icon-btn subtle file-add-btn ${uploadingFiles?'disabled':''}`} title="Adjuntar archivos"><Plus size={16}/><input type="file" multiple disabled={uploadingFiles} onChange={e=>{uploadFiles(Array.from(e.target.files||[]));e.target.value=''}}/></label></div>{uploadingFiles&&<div className="upload-progress"><span className="loader small-loader"/> Subiendo archivos…</div>}{(service.files||[]).length ? <div className="attached-files">{(service.files||[]).map(file=><div className="attached-file" key={file.id}><span className="attached-file-icon">{(file.type||'').startsWith('audio/')?<FileAudio size={16}/>:<FileText size={16}/>}</span><a href={file.url||'#'} target={file.url?'_blank':undefined} rel="noreferrer" onClick={e=>{if(!file.url)e.preventDefault()}}><strong>{file.name}</strong><small>{file.size?`${Math.max(1,Math.round(file.size/1024))} KB`:'Archivo adjunto'}</small></a><button className="icon-btn subtle" onClick={()=>removeFile(file)} title="Quitar archivo"><X size={14}/></button></div>)}</div>:<div className="file-empty"><Folder size={20}/><span>No hay archivos adjuntos</span><small>Sube partituras, audios o documentos (máx. 30 MB por archivo)</small><label className="file-upload-link"><Upload size={13}/> Seleccionar archivos<input type="file" multiple disabled={uploadingFiles} onChange={e=>{uploadFiles(Array.from(e.target.files||[]));e.target.value=''}}/></label></div>}</div></aside></div>}
    {tab==='teams' && <div className="detail-content"><div className="team-plan-head"><div><h2>Equipo asignado</h2><p>Distribuye las responsabilidades de este servicio por instrumento o función.</p></div><Btn variant="primary" onClick={()=>setModal({kind:'person',value:null})}><Plus size={16}/>Nuevo integrante</Btn></div><div className="assigned-team-grid">{groups.map((g,idx)=>{const instrument = g.name; const selectedIds = service.teamAssignments?.[instrument] ?? g.memberIds ?? []; const selectedPeople = people.filter(p=>selectedIds.includes(p.id));const eligible = people.filter(p=>(p.instruments||[]).some(i=>(g.instruments||[g.name]).includes(i)) || (g.name==='Coros'&&p.teams?.includes('Voces')) || (g.name==='Ministro'&&p.teams?.includes('Voces')) || (g.name==='FOH'&&p.teams?.includes('Audio')));return <div className="assigned-team-card" key={`${g.name}-${idx}`}><div className="assigned-team-head"><div className={`instrument-icon tint-${idx%5}`}>{instrumentIcon(g.name)}</div><div><h3>{g.name}</h3><small>{g.teamName || 'Equipo'}</small></div><button className="icon-btn subtle" onClick={()=>flash(`Puedes ajustar la asignación de ${g.name} desde esta lista.`)}><MoreHorizontal size={16}/></button></div><div className="assigned-members">{selectedPeople.length ? selectedPeople.map(p=><div className="assigned-member" key={p.id}><span className="avatar">{initials(`${p.firstName} ${p.lastName}`)}</span><span><strong>{p.firstName} {p.lastName}</strong><small>{p.role}</small></span><button className="remove-assignee" onClick={()=>toggleMember(instrument,p.id)}><X size={14}/></button></div>) : <div className="member-empty">Aún no hay integrantes asignados</div>}</div><div className="assign-picker"><label htmlFor={`assign-${idx}`}>Agregar integrante</label><select id={`assign-${idx}`} value="" onChange={e=>e.target.value&&toggleMember(instrument,e.target.value)}><option value="">Seleccionar persona…</option>{eligible.filter(p=>!selectedIds.includes(p.id)).map(p=><option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>)}{!eligible.filter(p=>!selectedIds.includes(p.id)).length&&people.filter(p=>!selectedIds.includes(p.id)).map(p=><option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>)}</select></div></div>})}</div><div className="team-hint"><ShieldCheck size={17}/><span>Las asignaciones se guardan en este servicio. Puedes reutilizar los equipos guardados para próximos servicios.</span></div></div>}
    {tab==='rehearse' && <div className="detail-content rehearse-layout"><div className="panel rehearsal-plan"><div className="rehearse-top"><div className="rehearsal-icon"><Headphones size={22}/></div><div><h2>Preparación del ensayo</h2><p>Reúne los detalles que el equipo necesita antes de tocar.</p></div></div><label className="field-label">Notas de ensayo</label><textarea className="rehearsal-textarea" value={service.rehearsalNotes||''} onChange={e=>servicesStore.upsert({...service,rehearsalNotes:e.target.value})} placeholder="Ej. Repasar el puente de la canción 2, confirmar entrada de voces…"/><div className="rehearsal-checklist"><h3>Checklist previo al servicio</h3>{['Confirmar tonalidades con el ministro','Revisar transiciones y finales','Probar monitoreo y microfonía','Compartir orden del servicio al equipo'].map((x,i)=><label key={x}><input type="checkbox"/> <span>{x}</span></label>)}</div></div><div className="panel rehearsal-songs"><SectionTitle title="Repertorio a ensayar" meta={`${(service.order||[]).flatMap(s=>s.items||[]).length} canciones`}/>{(service.order||[]).flatMap(s=>s.items||[]).length?(service.order||[]).flatMap(s=>s.items||[]).map(item=><div className="rehearsal-song-row" key={item.id}><span className="song-mini-icon"><Music2 size={15}/></span><span><strong>{item.title}</strong><small>{item.key} · {item.duration || 'Duración pendiente'}</small></span><button className="icon-btn subtle" onClick={()=>setModal({kind:'song',value:songs.find(s=>s.id===item.songId)||item})}><FileText size={15}/></button></div>):<p className="muted">Agrega canciones a la orden para preparar el ensayo.</p>}</div></div>}
  </>
}
function instrumentIcon(name) { if (/Batería/i.test(name)) return <Drum size={19}/>; if (/Guitarra/i.test(name)||/Bajo/i.test(name)) return <Guitar size={19}/>; if (/Key|Teclado/i.test(name)) return <Piano size={19}/>; if (/Voz|Ministro|Coro/i.test(name)) return <Mic2 size={19}/>; if (/Audio|FOH/i.test(name)) return <Volume2 size={19}/>; return <Music2 size={19}/> }

function SongsPage({ songs, songsStore, query, setQuery, setModal, flash }) {
  const [keyFilter, setKeyFilter] = useState('all')
  const [sort, setSort] = useState('title')
  const [selected, setSelected] = useState([])
  const filtered = useMemo(() => songs.filter(s => `${s.title} ${s.artist||''} ${(s.tags||[]).join(' ')} ${s.key||''}`.toLowerCase().includes(query.toLowerCase()) && (keyFilter==='all'||s.key===keyFilter)).sort((a,b)=>String(a[sort]||'').localeCompare(String(b[sort]||''))), [songs,query,keyFilter,sort])
  return <><PageHeading eyebrow="REPERTORIO" title="Canciones" description="Toda la música de tu iglesia, organizada y lista para cada servicio." actions={<><Btn onClick={()=>flash('Exportación preparada para una siguiente mejora.')}><Upload size={15}/>Exportar</Btn><Btn variant="primary" onClick={()=>setModal({kind:'song',value:null})}><Plus size={17}/>Agregar canción</Btn></>}/><div className="stat-strip"><div><span>Canciones registradas</span><strong>{songs.length}</strong></div><div><span>Tonalidades distintas</span><strong>{new Set(songs.map(s=>s.key).filter(Boolean)).size}</strong></div><div><span>Repertorio con BPM</span><strong>{songs.filter(s=>s.bpm).length}</strong></div><div className="stat-note"><span className="stat-mini-icon"><Music2 size={17}/></span><span>Un repertorio ordenado ayuda a preparar cada encuentro.</span></div></div><div className="panel song-library"><div className="library-toolbar"><div className="global-search-wrap"><Search size={17}/><input className="global-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por título, artista o etiqueta…"/></div><div className="filter-buttons"><select value={keyFilter} onChange={e=>setKeyFilter(e.target.value)}><option value="all">Todas las tonalidades</option>{[...new Set(songs.map(s=>s.key).filter(Boolean))].sort().map(k=><option key={k}>{k}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="title">Ordenar: título</option><option value="bpm">Ordenar: BPM</option><option value="key">Ordenar: tonalidad</option></select><button className="icon-btn bordered" onClick={()=>setSelected([])} title="Limpiar selección"><SlidersHorizontal size={16}/></button></div></div><div className="table-meta"><span>{filtered.length} canciones</span><div><button className="icon-btn subtle" onClick={()=>{const csv=['Título,Tono,BPM,Duración,Artista',...filtered.map(s=>`"${s.title}","${s.key||''}","${s.bpm||''}","${s.duration||''}","${s.artist||''}"`)].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='repertorio.csv';a.click();URL.revokeObjectURL(a.href)}} title="Descargar CSV"><Upload size={16}/></button><button className="icon-btn subtle" onClick={()=>setSelected(filtered.map(s=>s.id))} title="Seleccionar todos"><CheckCircle2 size={16}/></button></div></div><div className="data-table-wrap"><table className="data-table songs-table"><thead><tr><th><input type="checkbox" checked={filtered.length>0&&selected.length===filtered.length} onChange={e=>setSelected(e.target.checked?filtered.map(s=>s.id):[])}/></th><th>Título</th><th>Archivos</th><th>BPM</th><th>Tonalidad</th><th>Último servicio</th><th/></tr></thead><tbody>{filtered.map(song=><tr key={song.id}><td><input type="checkbox" checked={selected.includes(song.id)} onChange={e=>setSelected(prev=>e.target.checked?[...prev,song.id]:prev.filter(id=>id!==song.id))}/></td><td><button className="table-title-button" onClick={()=>setModal({kind:'song',value:song})}><span className="song-table-icon"><Music2 size={16}/></span><span><strong>{song.title}</strong><small>{song.artist||'Sin artista asignado'}</small></span></button></td><td><div className="file-indicators"><span title="Letra o acordes"><FileText size={15}/></span>{song.chords&&<span title="Acordes"><Guitar size={15}/></span>}{song.audioUrl&&<span title="Audio"><FileAudio size={15}/></span>}</div></td><td>{song.bpm || '—'}</td><td>{song.key ? <span className="key-pill">{song.key}</span> : '—'}</td><td className="muted">—</td><td><button className="icon-btn subtle" onClick={()=>setModal({kind:'song',value:song})}><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table>{filtered.length===0&&<div className="table-empty"><Music2 size={21}/><strong>No encontramos canciones</strong><span>Prueba otra búsqueda o agrega una canción nueva.</span></div>}</div><div className="table-bottom"><span>Mostrando {filtered.length} de {songs.length} canciones</span><div><button disabled><ChevronLeft size={15}/></button><button className="page-current">1</button><button disabled><ChevronRight size={15}/></button></div></div></div>{selected.length>0&&<div className="bulk-bar"><span>{selected.length} seleccionadas</span><Btn onClick={()=>{if(window.confirm(`¿Eliminar ${selected.length} canciones?`)){Promise.all(selected.map(id=>songsStore.remove(id)));setSelected([]);flash('Canciones eliminadas.')}}}><Trash2 size={15}/>Eliminar</Btn><Btn onClick={()=>setSelected([])}>Cancelar</Btn></div>}</>
}

function PeoplePage({ people, peopleStore, teams, teamsStore, query, setQuery, subtab, setSubtab, setModal, flash }) {
  const filtered=people.filter(p=>`${p.firstName} ${p.lastName} ${p.email} ${p.role} ${(p.instruments||[]).join(' ')}`.toLowerCase().includes(query.toLowerCase()))
  const [roleFilter,setRoleFilter]=useState('all')
  const visiblePeople=roleFilter==='all'?filtered:filtered.filter(p=>p.role===roleFilter)
  return <><PageHeading eyebrow="COMUNIDAD" title="Personas" description="Conoce a tus integrantes, administra sus roles y mantén los equipos coordinados." actions={<><Btn onClick={()=>setModal({kind:'team',value:null})}><Users size={16}/>Crear equipo</Btn><Btn variant="primary" onClick={()=>setModal({kind:'person',value:null})}><Plus size={17}/>Agregar persona</Btn></>}/><div className="subtabs people-tabs"><button className={subtab==='people'?'active':''} onClick={()=>setSubtab('people')}>Personas <span>{people.length}</span></button><button className={subtab==='teams'?'active':''} onClick={()=>setSubtab('teams')}>Equipos <span>{teams.length}</span></button></div>{subtab==='people'?<><div className="people-summary"><div className="people-summary-num"><strong>{people.length}</strong><span>Integrantes totales</span></div><div className="people-summary-num"><strong>{people.filter(p=>p.status!=='Inactivo').length}</strong><span>Activos</span></div><div className="people-summary-num"><strong>{people.filter(p=>p.role==='Líder'||p.role==='Administrador').length}</strong><span>Líderes y administradores</span></div><div className="people-avatars"><span className="avatar">{initials('Igor Rocha')}</span><span className="avatar">{initials('Catalina Arredondo')}</span><span className="avatar">{initials('Tomás Guajardo')}</span><span className="avatar avatar-more">+{Math.max(0,people.length-3)}</span></div></div><div className="panel people-table-panel"><div className="people-filter-row"><div className="global-search-wrap"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar personas por nombre, correo o instrumento…"/></div><div className="filter-buttons"><select value={roleFilter} onChange={e=>setRoleFilter(e.target.value)}><option value="all">Todos los roles</option>{[...new Set(people.map(p=>p.role).filter(Boolean))].map(r=><option key={r}>{r}</option>)}</select><button className="icon-btn bordered" onClick={()=>{setQuery('');setRoleFilter('all')}}><Filter size={16}/></button></div></div><div className="table-meta"><span>{visiblePeople.length} personas</span><div><button className="icon-btn subtle" onClick={()=>flash('Puedes exportar el directorio en una futura mejora.')}><Upload size={16}/></button><button className="icon-btn subtle" onClick={()=>setModal({kind:'person',value:null})}><Plus size={17}/></button></div></div><div className="data-table-wrap"><table className="data-table people-table"><thead><tr><th><input type="checkbox"/></th><th>Nombre</th><th>Correo electrónico</th><th>Teléfono</th><th>Permisos / rol</th><th>Equipos</th><th>Estado</th><th/></tr></thead><tbody>{visiblePeople.map(p=><tr key={p.id}><td><input type="checkbox"/></td><td><button className="person-cell" onClick={()=>setModal({kind:'person',value:p})}><span className="avatar">{initials(`${p.firstName} ${p.lastName}`)}</span><span><strong>{p.firstName} {p.lastName}</strong><small>{(p.instruments||[]).join(', ')||'Sin instrumento'}</small></span></button></td><td>{p.email||'—'}</td><td>{p.phone||'—'}</td><td><span className={`role-pill ${p.role==='Administrador'?'admin':p.role==='Líder'?'leader':''}`}>{p.role||'Músico'}</span></td><td><div className="team-pills">{(p.teams||[]).slice(0,2).map(t=><span key={t}>{t}</span>)}{!(p.teams||[]).length&&<span>—</span>}</div></td><td><span className={`status-pill ${p.status==='Inactivo'?'inactive':''}`}><i/>{p.status||'Activo'}</span></td><td><button className="icon-btn subtle" onClick={()=>setModal({kind:'person',value:p})}><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table>{!visiblePeople.length&&<div className="table-empty"><Users size={20}/><strong>No hay personas para mostrar</strong></div>}</div><div className="table-bottom"><span>Mostrando {visiblePeople.length} de {people.length} integrantes</span><div><button disabled><ChevronLeft size={15}/></button><button className="page-current">1</button><button disabled><ChevronRight size={15}/></button></div></div></div></>:<div className="teams-directory-grid">{teams.map(team=><div key={team.id} className="team-directory-card"><div className="team-card-title"><span className="team-avatar"><Users size={19}/></span><div><h3>{team.name}</h3><small>{(team.groups||[]).length} roles o secciones</small></div><button className="icon-btn subtle" onClick={()=>setModal({kind:'team',value:team})}><Edit3 size={15}/></button></div><div className="team-directory-groups">{(team.groups||[]).map((g,i)=><div key={i}><span>{g.name}</span><span className="avatar-stack">{(g.memberIds||[]).slice(0,3).map(id=>{const p=people.find(x=>x.id===id);return p?<span className="avatar" key={id} title={`${p.firstName} ${p.lastName}`}>{initials(`${p.firstName} ${p.lastName}`)}</span>:null})}<small>{(g.memberIds||[]).length}</small></span></div>)}</div><button className="team-card-footer" onClick={()=>setModal({kind:'team',value:team})}>Administrar equipo <ArrowRight size={14}/></button></div>)}<button className="add-team-card" onClick={()=>setModal({kind:'team',value:null})}><span><Plus size={22}/></span><strong>Crear nuevo equipo</strong><small>Organiza por función, instrumento o área</small></button></div>}</>
}

function TeamsPage({ teams, people, teamsStore, setModal, flash }) {
  return <><PageHeading eyebrow="ORGANIZACIÓN" title="Equipos" description="Agrupa músicos y voluntarios por instrumento, función o área de servicio." actions={<Btn variant="primary" onClick={()=>setModal({kind:'team',value:null})}><Plus size={16}/>Crear equipo</Btn>}/><div className="teams-directory-grid standalone-teams">{teams.map((team,i)=><div className="team-directory-card" key={team.id}><div className="team-card-title"><span className={`team-avatar tint-${i%5}`}><Users size={19}/></span><div><h3>{team.name}</h3><small>{(team.groups||[]).length} secciones · {(team.groups||[]).reduce((n,g)=>n+(g.memberIds||[]).length,0)} asignaciones</small></div><button className="icon-btn subtle" onClick={()=>setModal({kind:'team',value:team})}><MoreHorizontal size={17}/></button></div><div className="team-directory-groups">{(team.groups||[]).map((g,idx)=><div key={idx}><span className="role-with-icon">{instrumentIcon(g.name)}{g.name}</span><span className="avatar-stack">{(g.memberIds||[]).slice(0,3).map(id=>{const p=people.find(x=>x.id===id);return p?<span className="avatar" key={id}>{initials(`${p.firstName} ${p.lastName}`)}</span>:null})}<small>{(g.memberIds||[]).length}</small></span></div>)}</div><button className="team-card-footer" onClick={()=>setModal({kind:'team',value:team})}>Editar miembros y funciones <ArrowRight size={14}/></button></div>)}<button className="add-team-card" onClick={()=>setModal({kind:'team',value:null})}><span><Plus size={22}/></span><strong>Crear nuevo equipo</strong><small>Agrega instrumentos o equipos de servicio</small></button></div><div className="panel team-tip"><div className="tip-icon"><Sparkles size={18}/></div><div><strong>Una lista de equipo siempre actualizada</strong><p>Define quién toca cada instrumento y selecciona esas mismas personas al armar el equipo de cada servicio.</p></div></div></>
}

function MediaPage({ services, songs, setModal }) {
  const [tab,setTab]=useState('all')
  const items=[...songs.filter(s=>s.audioUrl||s.chords||s.lyrics).map(s=>({id:s.id,title:s.title,kind:s.audioUrl?'Audio':s.lyrics?'Letra y acordes':'Acordes',where:'Biblioteca de canciones',icon:s.audioUrl?FileAudio:FileText})),...services.flatMap(s=>(s.files||[]).map(f=>({...f,where:s.title,icon:FileText})))].filter(x=>tab==='all'||x.kind===tab)
  return <><PageHeading eyebrow="RECURSOS" title="Archivos y recursos" description="Encuentra letras, acordes y materiales de apoyo asociados a tus servicios." actions={<Btn variant="primary" onClick={()=>setModal({kind:'help'})}><Plus size={16}/>Añadir archivos</Btn>}/><div className="subtabs"><button className={tab==='all'?'active':''} onClick={()=>setTab('all')}>Todos los recursos</button><button className={tab==='Audio'?'active':''} onClick={()=>setTab('Audio')}>Audio</button><button className={tab==='Letra y acordes'?'active':''} onClick={()=>setTab('Letra y acordes')}>Letras y acordes</button></div><div className="media-grid">{items.map(item=>{const Icon=item.icon;return <div className="media-card" key={item.id}><div className="media-file-icon"><Icon size={23}/></div><div className="media-file-copy"><strong>{item.title}</strong><span>{item.kind||'Archivo'} · {item.where}</span></div><button className="icon-btn subtle" title="Ver detalles"><MoreHorizontal size={17}/></button></div>})}{!items.length&&<EmptyState icon={Folder} title="Tu biblioteca está lista para crecer" body="Agrega letras y acordes a las canciones, y aquí podrás encontrarlos organizados. Los archivos adjuntos se habilitan al integrar Firebase Storage."/>}</div><div className="storage-notice"><ShieldCheck size={17}/><span>Los campos de letra y acordes ya se guardan con cada canción. La carga de PDF, audio e imágenes necesita configurar Firebase Storage.</span></div></>
}

function MySchedule({ services, people, openService }) {
  const [filter,setFilter]=useState('upcoming')
  const ordered=[...services].sort((a,b)=>(a.date||'').localeCompare(b.date||'')).filter(s=>filter==='all'||s.date>=today.toISOString().slice(0,10))
  return <><PageHeading eyebrow="MI ESPACIO" title="Mi agenda" description="Consulta los próximos servicios y prepara tu participación." actions={<Btn onClick={()=>setFilter(filter==='all'?'upcoming':'all')}><Filter size={15}/>{filter==='all'?'Próximos':'Todos'}</Btn>}/><div className="schedule-timeline">{ordered.map(s=><button key={s.id} className="schedule-timeline-row" onClick={()=>openService(s)}><div className="timeline-date"><small>{new Intl.DateTimeFormat('es-CL',{month:'short'}).format(new Date(`${s.date}T12:00:00`)).toUpperCase()}</small><strong>{new Date(`${s.date}T12:00:00`).getDate()}</strong></div><div className="timeline-line"><i/></div><div className="timeline-card"><div><span className="eyebrow">{fmtDate(s.date,{weekday:'long'})} · {s.startTime}</span><h3>{s.title}</h3><p>{(s.order||[]).flatMap(x=>x.items||[]).length} canciones programadas · {(s.teamAssignments?Object.values(s.teamAssignments).flat().length:0)} asignaciones</p></div><span className="timeline-open">Abrir plan <ArrowRight size={15}/></span></div></button>)}{!ordered.length&&<EmptyState icon={CalendarDays} title="No hay servicios en tu agenda" body="Cuando se programen nuevos servicios aparecerán aquí."/>}</div></>
}

function SettingsPage({ cloud, user, services, onSeed, busy, flash }) {
  return <><PageHeading eyebrow="PREFERENCIAS" title="Configuración" description="Administra el espacio de tu iglesia y el estado de la conexión."/><div className="settings-grid"><div className="panel settings-card"><div className="settings-icon"><ShieldCheck size={20}/></div><h2>Conexión y datos</h2><p>{cloud?'La aplicación se encuentra conectada a Firebase. Los registros se sincronizan entre los integrantes con acceso.':'La aplicación está en modo de demostración y conserva los datos en este navegador.'}</p><div className="settings-status"><span className={`status-pill ${cloud?'':'inactive'}`}><i/>{cloud?'Firebase conectado':'Modo local'}</span><span>{user?.email||'Sin sesión de Firebase'}</span></div>{cloud&&services.length===0&&<Btn variant="primary" onClick={onSeed} disabled={busy}>{busy?'Cargando…':'Cargar datos de ejemplo'}</Btn>}{!cloud&&<div className="settings-next"><strong>Para habilitar la nube</strong><ol><li>Crea una app web en Firebase Console.</li><li>Completa las variables VITE_FIREBASE en Netlify.</li><li>Habilita Email/Password en Authentication.</li></ol></div>}</div><div className="panel settings-card"><div className="settings-icon lavender"><Users size={20}/></div><h2>Equipo de la iglesia</h2><p>El espacio de trabajo está identificado como Casa de Alabanza. Puedes editar los integrantes, equipos y funciones desde Personas.</p><button className="text-link" onClick={()=>flash('El nombre visible del espacio se personalizará en la próxima iteración.')}>Personalizar espacio <ArrowRight size={14}/></button></div><div className="panel settings-card"><div className="settings-icon peach"><LockKeyhole size={20}/></div><h2>Permisos y seguridad</h2><p>Los roles del directorio son informativos en esta versión. Para limitar acciones realmente por rol, deben reforzarse las reglas de Firebase y vincularlas a cuentas autenticadas.</p><button className="text-link" onClick={()=>flash('Consulta README.md para las instrucciones y reglas base de Firestore.')}>Ver recomendaciones <ArrowRight size={14}/></button></div></div></>
}

function ModalHost({ modal, setModal, onCreateService, onUpdateService, onDeleteService, onSaveSong, onDeleteSong, onSavePerson, onSaveType, onSaveTeam, songs, people, teams, serviceTypes, services }) {
  const [saving,setSaving]=useState(false)
  const [error,setError]=useState('')
  const close=()=>{setModal(null);setError('')}
  const value=modal.value||{}
  const save=async(fn,data)=>{setSaving(true);setError('');try{await fn(data)}catch(e){console.error(e);setError('No se pudieron guardar los cambios. Comprueba tu conexión y los permisos.')}finally{setSaving(false)}}
  const remove=async(fn,id)=>{if(!window.confirm('¿Seguro que deseas eliminar este registro?'))return;try{await fn(id);close()}catch(e){setError('No se pudo eliminar el registro.')}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className={`modal ${['song','person','team'].includes(modal.kind)?'modal-wide':''}`} role="dialog" aria-modal="true"><div className="modal-header"><div><span className="eyebrow">{modal.kind==='service'?'PLANIFICACIÓN':modal.kind==='song'?'REPERTORIO':modal.kind==='person'?'DIRECTORIO':modal.kind==='team'?'ORGANIZACIÓN':modal.kind==='type'?'PLANTILLAS':'AYUDA'}</span><h2>{modal.kind==='service'?(value.id?'Editar servicio':'Nuevo servicio'):modal.kind==='song'?(value.id?'Editar canción':'Agregar canción'):modal.kind==='person'?(value.id?'Editar integrante':'Agregar integrante'):modal.kind==='type'?(value.id?'Editar tipo de servicio':'Nuevo tipo de servicio'):modal.kind==='team'?(value.id?'Editar equipo':'Crear equipo'):modal.kind==='service-actions'?'Opciones del servicio':modal.kind==='section-edit'?'Editar sección':'Guía rápida'}</h2></div><button className="icon-btn subtle" onClick={close}><X size={20}/></button></div>
    {modal.kind==='service'&&<ServiceForm value={value} serviceTypes={serviceTypes} saving={saving} error={error} onSubmit={data=>save(value.id?onUpdateService:onCreateService,data)} onClose={close} />}
    {modal.kind==='song'&&<SongForm value={value} saving={saving} error={error} onSubmit={d=>save(onSaveSong,d)} onClose={close} onDelete={value.id?()=>remove(onDeleteSong,value.id):null}/>}
    {modal.kind==='person'&&<PersonForm value={value} teams={teams} saving={saving} error={error} onSubmit={d=>save(onSavePerson,d)} onClose={close}/>}
    {modal.kind==='type'&&<TypeForm value={value} saving={saving} error={error} onSubmit={d=>save(onSaveType,d)} onClose={close} />}
    {modal.kind==='team'&&<TeamForm value={value} people={people} saving={saving} error={error} onSubmit={d=>save(onSaveTeam,d)} onClose={close}/>}
    {modal.kind==='service-actions'&&<div className="modal-body action-options"><button onClick={()=>{setModal({kind:'service',value});}}><Edit3 size={17}/><span><strong>Editar datos del servicio</strong><small>Cambiar fecha, hora y tipo.</small></span></button><button onClick={()=>{const copy={...value,id:uid(),title:`${value.title} (copia)`,date:iso(Math.min(28,today.getDate()+7)),order:(value.order||[]).map(s=>({...s,id:uid(),items:(s.items||[]).map(i=>({...i,id:uid()}))}))};window.dispatchEvent(new CustomEvent('alabanza:duplicate-service',{detail:copy}));close()}}><Copy size={17}/><span><strong>Duplicar servicio</strong><small>Crear una copia para otra fecha.</small></span></button><button className="danger-option" onClick={()=>{onDeleteService(value.id);close()}}><Trash2 size={17}/><span><strong>Eliminar servicio</strong><small>Esta acción no se puede deshacer.</small></span></button><div className="modal-form-error">Nota: las acciones se procesan desde el detalle del servicio.</div></div>}
    {modal.kind==='section-edit'&&<SectionEditForm value={value.section} onClose={close} onSave={name=>{const svc=value.service;const order=(svc.order||[]).map(s=>s.id===value.section.id?{...s,name:name.toUpperCase()}:s);window.dispatchEvent(new CustomEvent('alabanza:section-update',{detail:{service:{...svc,order}}}));close()}}/>}
    {modal.kind==='help'&&<div className="modal-body help-modal-content"><p>Usa el menú lateral para entrar a cada área. Un flujo recomendado es:</p><ol><li><strong>Registra a los integrantes</strong> y agrúpalos en Banda, Voces y Audio.</li><li><strong>Completa el repertorio</strong> con tonalidades, BPM, letras y acordes.</li><li><strong>Crea un servicio</strong>, agrega secciones y selecciona las canciones.</li><li><strong>Asigna el equipo</strong> a cada función y comparte las notas de ensayo.</li></ol><p className="muted">En modo demo, los datos viven en este navegador. Configura Firebase para usar cuentas y sincronizar la información.</p><div className="modal-actions"><Btn variant="primary" onClick={close}>Entendido</Btn></div></div>}
  </div></div>
}

function ServiceForm({ value, serviceTypes, onSubmit, onClose, saving, error }) {
  const [title,setTitle]=useState(value.title||'');const [date,setDate]=useState(value.date||today.toISOString().slice(0,10));const [startTime,setStartTime]=useState(value.startTime||'11:00');const [typeId,setTypeId]=useState(value.typeId||serviceTypes[0]?.id||'')
  const submit=e=>{e.preventDefault();onSubmit({ ...value,title:title.trim(),date,startTime,typeId })}
  return <form className="modal-form" onSubmit={submit}><label>Nombre del servicio<input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ej. Servicio Domingo 11AM"/></label><div className="form-two"><label>Fecha<input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>Hora de inicio<input type="time" value={startTime} onChange={e=>setStartTime(e.target.value)}/></label></div><label>Tipo de servicio<select value={typeId} onChange={e=>{setTypeId(e.target.value);if(!title.trim())setTitle(serviceTypes.find(t=>t.id===e.target.value)?.name||'')}}><option value="">Seleccionar tipo…</option>{serviceTypes.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select></label>{error&&<div className="inline-alert">{error}</div>}<div className="modal-actions"><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit" disabled={saving}><Save size={15}/>{saving?'Guardando…':'Guardar servicio'}</Btn></div></form>
}
function SongForm({ value, onSubmit, onClose, onDelete, saving, error }) {
  const [title,setTitle]=useState(value.title||'');const [artist,setArtist]=useState(value.artist||'');const [key,setKey]=useState(value.key||'C');const [bpm,setBpm]=useState(value.bpm||'');const [duration,setDuration]=useState(value.duration||'');const [lyrics,setLyrics]=useState(value.lyrics||'');const [chords,setChords]=useState(value.chords||'');const [tags,setTags]=useState((value.tags||[]).join(', '));const [audioUrl,setAudioUrl]=useState(value.audioUrl||'')
  const submit=e=>{e.preventDefault();onSubmit({...value,title:title.trim(),artist:artist.trim(),key,bpm:bpm?Number(bpm):null,duration,lyrics,chords,tags:tags.split(',').map(x=>x.trim()).filter(Boolean),audioUrl:audioUrl.trim()})}
  return <form className="modal-form" onSubmit={submit}><div className="form-two"><label>Título de la canción<input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="Nombre de la canción"/></label><label>Artista / referencia<input value={artist} onChange={e=>setArtist(e.target.value)} placeholder="Autor o ministerio"/></label></div><div className="form-three"><label>Tonalidad<select value={key} onChange={e=>setKey(e.target.value)}>{['C','C#','Db','D','Eb','E','F','F#','Gb','G','Ab','A','Bb','B','Cm','C#m','Dm','Ebm','Em','Fm','F#m','Gm','G#m','Am','Bbm','Bm'].map(k=><option key={k}>{k}</option>)}</select></label><label>BPM<input type="number" min="1" max="300" value={bpm} onChange={e=>setBpm(e.target.value)} placeholder="72"/></label><label>Duración<input value={duration} onChange={e=>setDuration(e.target.value)} placeholder="4:30"/></label></div><label>Etiquetas<input value={tags} onChange={e=>setTags(e.target.value)} placeholder="Alabanza, Adoración (separadas por coma)"/></label><label>Acordes<textarea rows="2" value={chords} onChange={e=>setChords(e.target.value)} placeholder="Ej. G · D · Em · C"/></label><label>Letra<textarea rows="5" value={lyrics} onChange={e=>setLyrics(e.target.value)} placeholder="Pega la letra de la canción aquí…"/></label><label>Enlace de audio (opcional)<input type="url" value={audioUrl} onChange={e=>setAudioUrl(e.target.value)} placeholder="https://…"/></label>{error&&<div className="inline-alert">{error}</div>}<div className="modal-actions modal-actions-split">{onDelete&&<button className="danger-text" type="button" onClick={onDelete}><Trash2 size={15}/>Eliminar</button>}<span/><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit" disabled={saving}><Save size={15}/>{saving?'Guardando…':'Guardar canción'}</Btn></div></form>
}
function PersonForm({ value, teams, onSubmit, onClose, saving, error }) {
  const [firstName,setFirstName]=useState(value.firstName||'');const [lastName,setLastName]=useState(value.lastName||'');const [email,setEmail]=useState(value.email||'');const [phone,setPhone]=useState(value.phone||'');const [role,setRole]=useState(value.role||'Músico');const [status,setStatus]=useState(value.status||'Activo');const [instruments,setInstruments]=useState(value.instruments||[]);const [selectedTeams,setSelectedTeams]=useState(value.teams||[])
  const instrumentOptions=['Bajo','Batería','Guitarra acústica','Guitarra eléctrica','Teclado','Voz','Audio','Proyección','Dirección']
  const toggle=(list,set,item)=>set(list.includes(item)?list.filter(x=>x!==item):[...list,item])
  const submit=e=>{e.preventDefault();onSubmit({...value,firstName:firstName.trim(),lastName:lastName.trim(),email:email.trim(),phone:phone.trim(),role,status,instruments,teams:selectedTeams})}
  return <form className="modal-form" onSubmit={submit}><div className="form-two"><label>Nombre<input required value={firstName} onChange={e=>setFirstName(e.target.value)}/></label><label>Apellido<input required value={lastName} onChange={e=>setLastName(e.target.value)}/></label></div><div className="form-two"><label>Correo electrónico<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nombre@correo.cl"/></label><label>Teléfono<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+56 9 …"/></label></div><div className="form-two"><label>Rol / permisos<select value={role} onChange={e=>setRole(e.target.value)}>{['Administrador','Líder','Músico','Técnico','Invitado','Viewer'].map(r=><option key={r}>{r}</option>)}</select></label><label>Estado<select value={status} onChange={e=>setStatus(e.target.value)}><option>Activo</option><option>Inactivo</option></select></label></div><fieldset className="choice-field"><legend>Instrumentos y funciones</legend><div className="choice-grid">{instrumentOptions.map(item=><label key={item} className={instruments.includes(item)?'checked':''}><input type="checkbox" checked={instruments.includes(item)} onChange={()=>toggle(instruments,setInstruments,item)}/>{item}</label>)}</div></fieldset><fieldset className="choice-field"><legend>Equipos</legend><div className="choice-grid">{[...new Set([...teams.map(t=>t.name),'Banda','Voces','Audio'])].map(item=><label key={item} className={selectedTeams.includes(item)?'checked':''}><input type="checkbox" checked={selectedTeams.includes(item)} onChange={()=>toggle(selectedTeams,setSelectedTeams,item)}/>{item}</label>)}</div></fieldset>{error&&<div className="inline-alert">{error}</div>}<div className="modal-actions"><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit" disabled={saving}><Save size={15}/>{saving?'Guardando…':'Guardar integrante'}</Btn></div></form>
}
function TypeForm({ value, onSubmit, onClose, saving, error }) {
  const [name,setName]=useState(value.name||'');const [category,setCategory]=useState(value.category||'Servicio');const [color,setColor]=useState(value.color||'green')
  return <form className="modal-form" onSubmit={e=>{e.preventDefault();onSubmit({...value,name:name.trim(),category,color})}}><label>Nombre de la plantilla<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Servicio Domingo 11AM"/></label><label>Categoría<select value={category} onChange={e=>setCategory(e.target.value)}>{['Servicio','Reunión','Oración','Ensayo','Especial','Capacitación'].map(c=><option key={c}>{c}</option>)}</select></label><label>Color identificador<div className="color-options">{[['green','Verde'],['blue','Azul'],['violet','Violeta'],['rose','Rosa'],['amber','Ámbar'],['teal','Turquesa'],['slate','Gris']].map(([v,l])=><button type="button" key={v} className={`color-option ${v} ${color===v?'chosen':''}`} onClick={()=>setColor(v)}><i/>{l}{color===v&&<Check size={13}/>}</button>)}</div></label>{error&&<div className="inline-alert">{error}</div>}<div className="modal-actions"><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit" disabled={saving}><Save size={15}/>{saving?'Guardando…':'Guardar plantilla'}</Btn></div></form>
}
function TeamForm({ value, people, onSubmit, onClose, saving, error }) {
  const [name,setName]=useState(value.name||'');const [groups,setGroups]=useState(value.groups||[])
  const addGroup=()=>setGroups(prev=>[...prev,{name:'Nueva función',instruments:[],memberIds:[]}])
  const patchGroup=(idx,changes)=>setGroups(prev=>prev.map((g,i)=>i===idx?{...g,...changes}:g))
  const toggleMember=(idx,id)=>setGroups(prev=>prev.map((g,i)=>i===idx?{...g,memberIds:(g.memberIds||[]).includes(id)?g.memberIds.filter(x=>x!==id):[...(g.memberIds||[]),id]}:g))
  const submit=e=>{e.preventDefault();onSubmit({...value,name:name.trim(),groups})}
  return <form className="modal-form" onSubmit={submit}><label>Nombre del equipo<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Banda"/></label><div className="team-edit-groups"><div className="form-section-heading"><strong>Funciones e instrumentos</strong><button type="button" className="text-link" onClick={addGroup}><Plus size={14}/>Agregar función</button></div>{groups.map((g,i)=><div className="team-edit-group" key={i}><div className="team-edit-group-top"><input aria-label="Nombre de función" value={g.name} onChange={e=>patchGroup(i,{name:e.target.value})}/><button type="button" className="icon-btn subtle" onClick={()=>setGroups(prev=>prev.filter((_,j)=>j!==i))}><Trash2 size={15}/></button></div><input aria-label="Instrumentos separados por coma" value={(g.instruments||[]).join(', ')} onChange={e=>patchGroup(i,{instruments:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})} placeholder="Instrumentos separados por coma"/><div className="team-member-checks">{people.map(p=><label key={p.id}><input type="checkbox" checked={(g.memberIds||[]).includes(p.id)} onChange={()=>toggleMember(i,p.id)}/>{p.firstName} {p.lastName}</label>)}</div></div>)}{!groups.length&&<p className="muted">Agrega la primera función para este equipo.</p>}</div>{error&&<div className="inline-alert">{error}</div>}<div className="modal-actions"><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit" disabled={saving}><Save size={15}/>{saving?'Guardando…':'Guardar equipo'}</Btn></div></form>
}
function SectionEditForm({ value, onClose, onSave }) { const [name,setName]=useState(value.name||'');return <form className="modal-form" onSubmit={e=>{e.preventDefault();onSave(name)}}><label>Nombre de la sección<input required value={name} onChange={e=>setName(e.target.value)}/></label><div className="modal-actions"><Btn type="button" onClick={onClose}>Cancelar</Btn><Btn variant="primary" type="submit"><Save size={15}/>Guardar sección</Btn></div></form> }

// Bridge actions from modal menus back to the app state.
function AppEventsBridge({ onNavigate, onDuplicate, onDeleteService, onSectionUpdate }) {
  useEffect(()=>{
    const nav=e=>onNavigate(e.detail), dup=e=>onDuplicate(e.detail), del=e=>onDeleteService(e.detail), sec=e=>onSectionUpdate(e.detail)
    window.addEventListener('alabanza:navigate',nav);window.addEventListener('alabanza:duplicate-service',dup);window.addEventListener('alabanza:delete-service',del);window.addEventListener('alabanza:section-update',sec)
    return()=>{window.removeEventListener('alabanza:navigate',nav);window.removeEventListener('alabanza:duplicate-service',dup);window.removeEventListener('alabanza:delete-service',del);window.removeEventListener('alabanza:section-update',sec)}
  },[onNavigate,onDuplicate,onDeleteService,onSectionUpdate])
  return null
}

createRoot(document.getElementById('root')).render(<AppRoot />)
